// Builds the VT_I4 child identifier every get_acc*() entry point expects.
static VARIANT MakeChildVariant(int child_id)
{
    VARIANT var = {};
    VariantInit(&var);
    var.vt = VT_I4;
    var.lVal = child_id;
    return var;
}

// Copies a BSTR the callee allocated into a strdup()ed UTF-8 string and
// releases it. A null BSTR means the get_acc*() call failed.
static char* DuplicateBstr(BSTR value)
{
    if (!value)
    {
        return nullptr;
    }

    const wxString converted = wxConvertStringFromOle(value);
    SysFreeString(value);
    return strdup(converted.utf8_string().data());
}

// Records a get_acc*() call's HRESULT for a *WithStatus entry point. The C surface
// reports 0 for S_OK and any other value for a call that failed.
static void StoreStatus(int* result, HRESULT status)
{
    if (result)
    {
        *result = static_cast<int>(status);
    }
}

