    char* MSAAGetRoleTextWithStatus(void* accessible, int child_id, int* result)
    {
        if (!accessible)
        {
            StoreStatus(result, E_FAIL);
            return nullptr;
        }

        VARIANT var_child = MakeChildVariant(child_id);
        VARIANT var_role = {};
        VariantInit(&var_role);
        const HRESULT status =
            static_cast<IAccessible*>(accessible)->get_accRole(var_child, &var_role);
        VariantClear(&var_child);
        // get_accRole() is the call that can fail; GetRoleText() has no status of its own.
        StoreStatus(result, status);
        if (FAILED(status) || var_role.vt != VT_I4)
        {
            VariantClear(&var_role);
            return nullptr;
        }

        // GetRoleText() writes a wide string and leaves it empty for an unknown role.
        TCHAR role_buffer[256] = {};
        GetRoleText(static_cast<DWORD>(var_role.lVal), role_buffer, 256);
        VariantClear(&var_role);

        const wxString role_text(role_buffer);
        return strdup(role_text.utf8_string().data());
    }

